            ("Country", movie.get("country")),
            ("Language", movie.get("language")),
            ("Location", movie.get("location")),
            ("Director", metadata.get("director")),
            ("Producer", metadata.get("producer")),
            ("Studios", metadata.get("studios")),
            ("Genre", metadata.get("genre")),
