def parse_int_arg(name: str, default: int, *, minimum: int = 0, maximum: int = 1000) -> int:
    raw = request.args.get(name, str(default))
    try:
        value = int(raw)
    except (TypeError, ValueError) as exc:
        raise NextApiError(f"Invalid integer value for {name}", 400) from exc
    return min(max(value, minimum), maximum)


def parse_uuid(value: Any, field_name: str) -> UUID | None:
    if value in (None, ""):
        return None
    try:
        return UUID(str(value))
    except ValueError as exc:
        raise NextApiError(f"Invalid UUID for {field_name}", 400) from exc


def parse_bool_value(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off"}:
        return False
    return default


def normalize_media_group_member_role(value: Any) -> str:
    role = str(value or "member").strip().lower().replace(" ", "_")
    if role not in MEDIA_GROUP_MEMBER_ROLES:
        raise NextApiError("Invalid media group role", 400)
    return role


def can_manage_media_group_members(conn, group_id: UUID, actor: dict[str, Any]) -> bool:
    if actor.get("role") in {"owner", "admin"}:
        return True
    actor_id = actor.get("id")
    if not actor_id:
        return True
    if not table_exists(conn, "media_group_members"):
        return False
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT role
            FROM media_group_members
            WHERE group_id=%s AND user_id=%s
            """,
            (group_id, actor_id),
        )
        member = cur.fetchone()
    return bool(member and member.get("role") in {"owner", "manager"})


def parse_uuid_list(values: Any, field_name: str, *, maximum: int = 250) -> list[UUID]:
    if values in (None, ""):
        return []
    if not isinstance(values, list):
        raise NextApiError(f"{field_name} must be an array", 400)
    if len(values) > maximum:
        raise NextApiError(f"At most {maximum} {field_name} values are allowed", 400)
    parsed: list[UUID] = []
    seen: set[UUID] = set()
    for value in values:
        item = parse_uuid(value, field_name)
        if not item:
            raise NextApiError(f"{field_name} must not contain empty values", 400)
        if item not in seen:
            parsed.append(item)
            seen.add(item)
    return parsed


def require_existing_movie_ids(conn, movie_ids: list[UUID]) -> None:
    if not movie_ids:
        return
    if not table_exists(conn, "movies"):
        raise NextApiError("Movie table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE id = ANY(%s)", (movie_ids,))
        found_ids = {row["id"] for row in cur.fetchall()}
    missing = [str(item) for item in movie_ids if item not in found_ids]
    if missing:
        raise NextApiError(f"Movie not found: {', '.join(missing)}", 404)


def container_type_for_id(conn, container_id: UUID) -> str:
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT container_type FROM containers WHERE id=%s", (container_id,))
        row = cur.fetchone()
    if not row:
        raise NextApiError("Container not found", 404)
    return str(row["container_type"] or "")


def container_types_for_ids(conn, container_ids: list[UUID]) -> dict[UUID, str]:
    if not container_ids:
        return {}
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id, container_type FROM containers WHERE id = ANY(%s)", (container_ids,))
        rows = cur.fetchall()
    found = {row["id"]: str(row["container_type"] or "") for row in rows}
    missing = [str(item) for item in container_ids if item not in found]
    if missing:
        raise NextApiError(f"Container not found: {', '.join(missing)}", 404)
    return found


def normalize_container_type(value: Any) -> str:
    container_type = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if container_type not in {"box_set", "collection", "vault"}:
        raise NextApiError("containerType must be box_set, collection or vault", 400)
    return container_type


def container_payload(body: dict[str, Any], *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    existing = existing or {}
    title = clean_text(body.get("title")) if "title" in body else existing.get("title")
    if not title:
        raise NextApiError("Container title is required", 400)
    if len(title) > 240:
        raise NextApiError("Container title must be 240 characters or fewer", 400)
    description = clean_text(body.get("description")) if "description" in body else existing.get("description")
    if description and len(description) > 2000:
        raise NextApiError("Container description must be 2000 characters or fewer", 400)
    year = clean_text(body.get("year")) if "year" in body else existing.get("year")
    if year and len(year) > 40:
        raise NextApiError("Container year must be 40 characters or fewer", 400)
    barcode = clean_text(body.get("barcode")) if "barcode" in body else existing.get("barcode")
    if barcode and len(barcode) > 160:
        raise NextApiError("Container barcode must be 160 characters or fewer", 400)
    if "badgeLabel" in body or "badge_label" in body:
        badge_label = clean_text(body.get("badgeLabel", body.get("badge_label")))
    else:
        badge_label = existing.get("badge_label")
    if badge_label and len(badge_label) > 80:
        raise NextApiError("Container badge must be 80 characters or fewer", 400)
    metadata = body.get("metadata") if isinstance(body.get("metadata"), dict) else existing.get("metadata") or {}
    return {
        "title": title,
        "description": description,
        "year": year,
        "barcode": barcode,
        "badge_label": badge_label,
        "metadata": metadata,
    }


def ensure_sync_state(conn) -> int:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO sync_state (id, revision)
            VALUES ('global', 0)
            ON CONFLICT (id) DO NOTHING
            """
        )
        cur.execute("SELECT revision FROM sync_state WHERE id='global'")
        row = cur.fetchone()
    return int(row["revision"] if row else 0)


def current_revision(conn) -> int:
    if not table_exists(conn, "sync_state"):
        return 0
    return ensure_sync_state(conn)


def next_revision(conn) -> int:
    with conn.cursor() as cur:
        cur.execute(
            """
            UPDATE sync_state
            SET revision = revision + 1,
                updated_at = now()
            WHERE id='global'
            RETURNING revision
            """
        )
        row = cur.fetchone()
    if not row:
        ensure_sync_state(conn)
        return next_revision(conn)
    return int(row["revision"])


def sync_change(
    conn,
    *,
    revision: int,
    entity_type: str,
    entity_id: str,
    operation: str,
    payload: dict[str, Any],
) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO sync_changes (
                revision,
                entity_type,
                entity_id,
                operation,
                payload
            )
            VALUES (%s, %s, %s, %s, %s)
            """,
            (revision, entity_type, entity_id, operation, Jsonb(json_ready(payload))),
        )


def idempotency_key(client_id: str, client_mutation_id: str) -> str:
    return f"sync:{client_id}:{client_mutation_id}"


def stored_idempotency_response(conn, key: str) -> dict[str, Any] | None:
    with conn.cursor() as cur:
        cur.execute("SELECT response FROM idempotency_records WHERE key=%s", (key,))
        row = cur.fetchone()
    return dict(row["response"]) if row else None


def store_idempotency_response(
    conn,
    *,
    key: str,
    operation: str,
    status: str,
    entity_type: str,
    entity_id: UUID | None,
    response_payload: dict[str, Any],
) -> None:
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO idempotency_records (
                key,
                operation,
                status,
                entity_type,
                entity_id,
                response
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            ON CONFLICT (key) DO UPDATE SET
                updated_at=now()
            """,
            (key, operation, status, entity_type, entity_id, Jsonb(json_ready(response_payload))),
        )


def app_settings_map(conn) -> dict[str, Any]:
    if not table_exists(conn, "app_settings"):
        return {}
    with conn.cursor() as cur:
        cur.execute("SELECT key, value FROM app_settings WHERE is_secret = false")
        return {row["key"]: row["value"] for row in cur.fetchall()}


def normalized_app_preference_key(key: Any) -> str:
    text = str(key or "").strip()
    return APP_PREFERENCE_ALIASES.get(text, text)


def validate_app_preference(key: str, value: Any) -> Any:
    key = normalized_app_preference_key(key)
    if key not in APP_PREFERENCE_DEFAULTS:
        raise NextApiError(f"Unknown preference: {key}", 400)
    if key in APP_BOOLEAN_PREFERENCES:
        return parse_bool_value(value, default=bool(APP_PREFERENCE_DEFAULTS[key]))
    if key in APP_CHOICE_PREFERENCES:
        text = str(value or APP_PREFERENCE_DEFAULTS[key]).strip()
        text = text.upper() if key == "rating_country" else text.lower()
        if text not in APP_CHOICE_PREFERENCES[key]:
            raise NextApiError(f"Invalid value for preference {key}", 400)
        return text
    if key == "default_media_group_id":
        text = str(value or "").strip()
        if text:
            parse_uuid(text, "defaultMediaGroupId")
        return text
    return value


def app_global_preferences(conn) -> dict[str, Any]:
    values = dict(APP_PREFERENCE_DEFAULTS)
    settings = app_settings_map(conn)
    for key in APP_PREFERENCE_DEFAULTS:
        if key in settings:
            values[key] = validate_app_preference(key, settings[key])
    if "show_search_button" in settings and "show_collection_search" not in settings:
        values["show_collection_search"] = validate_app_preference("show_collection_search", settings["show_search_button"])
    return values


def app_user_preferences(conn, user_id: UUID | str | None) -> dict[str, Any]:
    if not user_id or not table_exists(conn, "user_preferences"):
        return {}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT key, value
            FROM user_preferences
            WHERE user_id=%s
            """,
            (user_id,),
        )
        rows = cur.fetchall()
    values: dict[str, Any] = {}
    for row in rows:
        key = normalized_app_preference_key(row["key"])
        if key not in APP_PREFERENCE_DEFAULTS:
            continue
        values[key] = validate_app_preference(key, row["value"])
    return values


def app_effective_preferences(conn, user_id: UUID | str | None = None) -> dict[str, Any]:
    values = app_global_preferences(conn)
    values.update(app_user_preferences(conn, user_id))
    return values


def set_app_user_preferences(conn, user_id: UUID | str, updates: dict[str, Any]) -> dict[str, Any]:
    if not table_exists(conn, "user_preferences"):
        raise NextApiError("User preferences table is not available", 503)
    normalized: dict[str, Any] = {}
    for raw_key, raw_value in updates.items():
        key = normalized_app_preference_key(raw_key)
        normalized[key] = validate_app_preference(key, raw_value)
    with conn.cursor() as cur:
        for key, value in normalized.items():
            cur.execute(
                """
                INSERT INTO user_preferences (user_id, key, value, updated_at)
                VALUES (%s, %s, %s, now())
                ON CONFLICT (user_id, key) DO UPDATE SET
                    value=EXCLUDED.value,
                    updated_at=now()
                """,
                (user_id, key, Jsonb(json_ready(value))),
            )
    return app_effective_preferences(conn, user_id)


def reconcile_legacy_metadata_plugins(conn) -> dict[str, Any] | None:
    if not table_exists(conn, "app_settings") or not table_exists(conn, "metadata_plugins"):
        return None
    settings = app_settings_map(conn)
    if not settings or "legacy_metadata_plugins_reconciled" in settings:
        return None
    legacy_keys = {
        "metadata_source_order",
        "tmdb_enabled",
        "omdb_enabled",
        "movievault_enabled",
        "bluray_scrape_enabled",
        "bluray_com_enabled",
        "upcitemdb_enabled",
    }
    if not any(key in settings for key in legacy_keys):
        return None
    return apply_legacy_metadata_plugin_plan(conn, settings, Jsonb)


def sync_metadata_plugin_registry(conn) -> None:
    sync_plugin_registry(conn, table_exists, Jsonb)
    if reconcile_legacy_metadata_plugins(conn):
        sync_plugin_registry(conn, table_exists, Jsonb)


def next_user_primary_role(conn, user_id: UUID | str) -> str | None:
    if not table_exists(conn, "user_roles") or not table_exists(conn, "roles"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT r.key
            FROM user_roles ur
            JOIN roles r ON r.id = ur.role_id
            WHERE ur.user_id=%s
            ORDER BY
                CASE r.key
                    WHEN 'owner' THEN 0
                    WHEN 'admin' THEN 1
                    ELSE 2
                END,
                r.key
            LIMIT 1
            """,
            (user_id,),
        )
        row = cur.fetchone()
    return row["key"] if row else None


def next_profile_user_payload(conn, user: dict[str, Any]) -> dict[str, Any]:
    user_id = user["id"]
    avatar: dict[str, Any] | None = None
    fresh_user = user
    if table_exists(conn, "users"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    u.id,
                    u.username,
                    u.display_name,
                    u.first_name,
                    u.last_name,
                    u.status,
                    u.avatar_asset_id,
                    u.updated_at,
                    ma.id AS avatar_id,
                    ma.kind AS avatar_kind,
                    ma.variant AS avatar_variant,
                    ma.storage_backend AS avatar_storage_backend,
                    ma.storage_key AS avatar_storage_key,
                    ma.source_url AS avatar_source_url,
                    ma.provider_id AS avatar_provider_id,
                    ma.content_type AS avatar_content_type,
                    ma.width AS avatar_width,
                    ma.height AS avatar_height,
                    ma.size_bytes AS avatar_size_bytes,
                    ma.sha256 AS avatar_sha256,
                    ma.metadata AS avatar_metadata,
                    ma.created_at AS avatar_created_at
                FROM users u
                LEFT JOIN media_assets ma ON ma.id = u.avatar_asset_id
                WHERE u.id=%s
                """,
                (user_id,),
            )
            row = cur.fetchone()
        if row:
            fresh_user = row
            if row.get("avatar_id"):
                avatar = {
                    "id": row.get("avatar_id"),
                    "kind": row.get("avatar_kind"),
                    "variant": row.get("avatar_variant"),
                    "storage_backend": row.get("avatar_storage_backend"),
                    "storage_key": row.get("avatar_storage_key"),
                    "source_url": row.get("avatar_source_url"),
                    "provider_id": row.get("avatar_provider_id"),
                    "content_type": row.get("avatar_content_type"),
                    "width": row.get("avatar_width"),
                    "height": row.get("avatar_height"),
                    "size_bytes": row.get("avatar_size_bytes"),
                    "sha256": row.get("avatar_sha256"),
                    "metadata": row.get("avatar_metadata"),
                    "created_at": row.get("avatar_created_at"),
                }
    avatar_url = media_asset_public_url(avatar)
    display_name = fresh_user.get("display_name") or fresh_user.get("username")
    return {
        "id": fresh_user.get("id"),
        "username": fresh_user.get("username"),
        "displayName": display_name,
        "display_name": display_name,
        "first_name": fresh_user.get("first_name"),
        "last_name": fresh_user.get("last_name"),
        "role": fresh_user.get("role") or next_user_primary_role(conn, user_id),
        "avatarAssetId": fresh_user.get("avatar_asset_id"),
        "avatar_asset_id": fresh_user.get("avatar_asset_id"),
        "avatarUrl": avatar_url,
        "avatar_url": avatar_url,
        "updated_at": fresh_user.get("updated_at"),
    }


def next_profile_recovery_payload(conn, user_id: UUID | str) -> dict[str, Any]:
    if not table_exists(conn, "recovery_codes"):
        return {
            "available": False,
            "activeCount": 0,
            "usedCount": 0,
            "lastGeneratedAt": None,
        }
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                COUNT(*) FILTER (
                    WHERE used_at IS NULL
                      AND (expires_at IS NULL OR expires_at > now())
                )::int AS active_count,
                COUNT(*) FILTER (WHERE used_at IS NOT NULL)::int AS used_count,
                MAX(created_at) AS last_generated_at
            FROM recovery_codes
            WHERE user_id=%s
            """,
            (user_id,),
        )
        row = cur.fetchone() or {}
    return {
        "available": True,
        "activeCount": int(row.get("active_count") or 0),
        "usedCount": int(row.get("used_count") or 0),
        "lastGeneratedAt": row.get("last_generated_at"),
    }


def require_next_admin_user(conn) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {"id": None, "username": "system", "role": "owner"}
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    if role not in {"owner", "admin"}:
        raise NextApiError("Admin access required", 403)
    user["role"] = role
    return user


def next_user_permission_keys(conn, user_id: UUID | str) -> set[str]:
    if not table_exists(conn, "user_roles") or not table_exists(conn, "role_permissions"):
        return set()
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT DISTINCT rp.permission_key
            FROM user_roles ur
            JOIN role_permissions rp ON rp.role_id = ur.role_id
            WHERE ur.user_id=%s
            """,
            (user_id,),
        )
        return {str(row["permission_key"]) for row in cur.fetchall()}


def require_next_permission(conn, permission_key: str) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {
            "id": None,
            "username": "system",
            "role": "owner",
            "permissions": ["*"],
        }
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    permissions = next_user_permission_keys(conn, user["id"])
    if role != "owner" and permission_key not in permissions:
        raise NextApiError(f"Permission required: {permission_key}", 403)
    user["role"] = role
    user["permissions"] = sorted(permissions)
    return user


def require_any_next_permission(conn, permission_keys: tuple[str, ...]) -> dict[str, Any]:
    if not next_auth_effective_enabled(conn, table_exists):
        return {
            "id": None,
            "username": "system",
            "role": "owner",
            "permissions": ["*"],
        }
    user = next_auth_current_user(conn)
    if not user:
        raise NextApiError("Unauthorized", 401)
    role = next_user_primary_role(conn, user["id"])
    permissions = next_user_permission_keys(conn, user["id"])
    if role != "owner" and not permissions.intersection(permission_keys):
        raise NextApiError(f"One of these permissions is required: {', '.join(permission_keys)}", 403)
    user["role"] = role
    user["permissions"] = sorted(permissions)
    return user


PLUGIN_REGISTRY_VIEW_PERMISSIONS = (
    "metadata.manage_plugins",
    "metadata.view_plugin_health",
    "metadata.manage_plugin_settings",
    "metadata.manage_receivers",
    "metadata.search",
    "metadata.refresh_one",
    "metadata.refresh_bulk",
    "digital_sources.view",
    "digital_sources.connect",
    "digital_sources.sync",
    "digital_sources.manage",
    "collection.import",
    "admin.view_settings",
)
PLUGIN_REGISTRY_MANAGE_PERMISSIONS = (
    "metadata.manage_plugins",
    "metadata.manage_plugin_settings",
    "metadata.manage_receivers",
    "digital_sources.connect",
    "digital_sources.manage",
    "collection.import",
)


def plugin_category_set(plugin: dict[str, Any]) -> set[str]:
    manifest = plugin.get("manifest") or {}
    categories = plugin.get("categories") or manifest.get("categories") or []
    return {str(item) for item in categories}


def plugin_action_permissions(plugin: dict[str, Any], entrypoint: str = "") -> tuple[str, ...]:
    categories = plugin_category_set(plugin)
    if entrypoint == "sync_library":
        return ("digital_sources.sync", "digital_sources.manage")
    if entrypoint in {"discover_library", "playback_deeplink"}:
        return ("digital_sources.view", "digital_sources.connect", "digital_sources.manage")
    if entrypoint in {"inspect_source", "plan_import", "import_source"}:
        return ("collection.import", "admin.restore_functional")
    if entrypoint == "receive_metadata":
        return ("metadata.manage_receivers", "metadata.manage_plugins")
    if entrypoint == "health_check":
        permissions = ["metadata.view_plugin_health", "metadata.manage_plugins"]
        if "digital_media_source" in categories:
            permissions.extend(["digital_sources.view", "digital_sources.connect", "digital_sources.manage"])
        if "import_source" in categories:
            permissions.extend(["collection.import", "admin.restore_functional"])
        return tuple(dict.fromkeys(permissions))
    if "import_source" in categories:
        return ("collection.import", "admin.restore_functional")
    if "digital_media_source" in categories:
        return ("digital_sources.view", "digital_sources.connect", "digital_sources.sync", "digital_sources.manage")
    return (
        "metadata.search",
        "metadata.refresh_one",
        "metadata.refresh_bulk",
        "metadata.manage_plugins",
    )


def plugin_manage_permissions(plugin: dict[str, Any]) -> tuple[str, ...]:
    categories = plugin_category_set(plugin)
    permissions: list[str] = []
    if {"metadata_source", "metadata_receiver"}.intersection(categories):
        permissions.extend(["metadata.manage_plugins", "metadata.manage_plugin_settings"])
    if "metadata_receiver" in categories:
        permissions.append("metadata.manage_receivers")
    if "digital_media_source" in categories:
        permissions.extend(["digital_sources.connect", "digital_sources.manage"])
    if "import_source" in categories:
        permissions.append("collection.import")
    return tuple(dict.fromkeys(permissions or list(PLUGIN_REGISTRY_MANAGE_PERMISSIONS)))


def require_plugin_action_permission(conn, plugin: dict[str, Any], entrypoint: str = "") -> dict[str, Any]:
    return require_any_next_permission(conn, plugin_action_permissions(plugin, entrypoint))


def plugin_requires_config_for_entrypoint(plugin: dict[str, Any], config: dict[str, Any], entrypoint: str) -> bool:
    if entrypoint in {"health_check", "discover_library", "playback_deeplink"}:
        return False
    if str(plugin.get("id") or "") == MOVIEVAULT_PLUGIN_ID:
        return False
    manifest = plugin.get("manifest") or {}
    return bool(plugin.get("requiresSecrets") or manifest.get("requiresSecrets")) and not bool(config.get("secretsConfigured"))


def uploaded_backup_file_path(destination_dir: Path) -> Path:
    upload = request.files.get("file") or request.files.get("backup")
    if not upload or not upload.filename:
        raise NextApiError("Upload a backup ZIP as multipart field 'file'", 400)
    if not upload.filename.lower().endswith(".zip"):
        raise NextApiError("Backup upload must be a .zip file", 400)
    destination_dir.mkdir(parents=True, exist_ok=True)
    target = destination_dir / f"{uuid.uuid4()}.zip"
    upload.save(target)
    return target


def plugin_secret_key(plugin_id: str, secret_name: str) -> str:
    name = str(secret_name or "").strip()
    if not PLUGIN_SECRET_NAME_PATTERN.match(name):
        raise NextApiError(
            "Secret names may only contain letters, numbers, dots, dashes and underscores",
            400,
        )
    return f"plugin_secret:{plugin_id}:{name}"


def plugin_is_metadata(categories: Any) -> bool:
    values = {str(item) for item in (categories or [])}
    return bool({"metadata_source", "metadata_receiver"}.intersection(values))


def plugin_config_payload(settings: Any, secrets_ref: Any) -> dict[str, Any]:
    safe_settings = settings if isinstance(settings, dict) else {}
    refs = secrets_ref if isinstance(secrets_ref, dict) else {}
    safe_refs: dict[str, dict[str, Any]] = {}
    for name, ref in refs.items():
        if not PLUGIN_SECRET_NAME_PATTERN.match(str(name)):
            continue
        key = ref.get("key") if isinstance(ref, dict) else ref
        item: dict[str, Any] = {"configured": True}
        if key:
            item["key"] = str(key)
        safe_refs[str(name)] = item
    return {
        "settings": safe_settings,
        "settingsConfigured": bool(safe_settings),
        "secretNames": sorted(safe_refs),
        "secretsConfigured": bool(safe_refs),
        "secretsRef": safe_refs,
    }


def plugin_config_from_db(conn, plugin_id: str) -> dict[str, Any]:
    if not table_exists(conn, "plugin_settings"):
        return plugin_config_payload({}, {})
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT settings, secrets_ref
            FROM plugin_settings
            WHERE plugin_id=%s
            """,
            (plugin_id,),
        )
        row = cur.fetchone()
    return plugin_config_payload(
        row.get("settings") if row else {},
        row.get("secrets_ref") if row else {},
    )


def plugin_secret_values(conn, config: dict[str, Any]) -> dict[str, Any]:
    refs = config.get("secretsRef") or {}
    keys = [
        str(ref.get("key"))
        for ref in refs.values()
        if isinstance(ref, dict) and ref.get("key")
    ]
    if not keys or not table_exists(conn, "app_settings"):
        return {}
    values: dict[str, Any] = {}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT key, value
            FROM app_settings
            WHERE key = ANY(%s) AND is_secret = true
            """,
            (keys,),
        )
        rows = cur.fetchall()
    by_key = {row["key"]: row["value"] for row in rows}
    for name, ref in refs.items():
        key = ref.get("key") if isinstance(ref, dict) else None
        if key in by_key:
            values[str(name)] = by_key[key]
    return values


def plugin_execution_context(
    conn,
    plugin: dict[str, Any],
    config: dict[str, Any],
    actor: dict[str, Any] | None = None,
    *,
    ensure_movievault_token: bool = False,
) -> dict[str, Any]:
    manifest = plugin.get("manifest") or {}
    context = {
        "pluginId": plugin.get("id"),
        "pluginName": plugin.get("name"),
        "enabled": bool(plugin.get("enabled")),
        "categories": plugin.get("categories") or manifest.get("categories") or [],
        "capabilities": plugin.get("capabilities") or manifest.get("capabilities") or [],
        "settings": config.get("settings") or {},
        "secrets": plugin_secret_values(conn, config),
        "settingsConfigured": bool(config.get("settingsConfigured")),
        "secretNames": config.get("secretNames") or [],
        "secretsConfigured": bool(config.get("secretsConfigured")),
        "actor": {
            "id": str(actor.get("id")) if actor and actor.get("id") else None,
            "username": actor.get("username") if actor else None,
            "role": actor.get("role") if actor else None,
        },
    }
    return movievault_plugin_context(
        conn,
        str(plugin.get("id") or ""),
        context,
        ensure_token=ensure_movievault_token,
        actor_id=actor.get("id") if actor else None,
    )


def validate_plugin_execution_request(plugin: dict[str, Any], body: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    entrypoint = str(body.get("entrypoint") or "").strip()
    if not entrypoint:
        raise NextApiError("entrypoint is required", 400)
    runtime = plugin.get("runtime") or {}
    entrypoints = runtime.get("entrypoints") or []
    if entrypoint not in entrypoints:
        raise NextApiError(f"Plugin entrypoint is not available: {entrypoint}", 400)
    if entrypoint != "health_check" and not plugin.get("enabled"):
        raise NextApiError("Plugin must be enabled before execution", 409)
    payload = body.get("payload") or {}
    if not isinstance(payload, dict):
        raise NextApiError("payload must be an object", 400)
    return entrypoint, payload


def update_plugin_config(
    conn,
    *,
    plugin_id: str,
    categories: Any,
    actor_id: UUID | str | None,
    settings_provided: bool,
    settings_value: Any,
    secrets_provided: bool,
    secrets_value: Any,
) -> None:
    if not table_exists(conn, "plugin_settings"):
        raise NextApiError("Plugin settings table is not available", 503)
    if settings_provided and not isinstance(settings_value, dict):
        raise NextApiError("settings must be an object", 400)
    if secrets_provided and not isinstance(secrets_value, dict):
        raise NextApiError("secrets must be an object", 400)

    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT settings, secrets_ref
            FROM plugin_settings
            WHERE plugin_id=%s
            """,
            (plugin_id,),
        )
        existing = cur.fetchone()

    settings = dict(existing.get("settings") or {}) if existing else {}
    secrets_ref = dict(existing.get("secrets_ref") or {}) if existing else {}
    if settings_provided:
        settings = dict(settings_value or {})

    with conn.transaction():
        with conn.cursor() as cur:
            if secrets_provided:
                for raw_name, secret_value in secrets_value.items():
                    secret_name = str(raw_name or "").strip()
                    secret_key = plugin_secret_key(plugin_id, secret_name)
                    if secret_value is None or secret_value == "":
                        cur.execute("DELETE FROM app_settings WHERE key=%s", (secret_key,))
                        secrets_ref.pop(secret_name, None)
                        continue
                    if isinstance(secret_value, (dict, list)):
                        raise NextApiError("Secret values must be scalar JSON values", 400)
                    cur.execute(
                        """
                        INSERT INTO app_settings (key, value, is_secret, updated_at, updated_by)
                        VALUES (%s, %s, true, now(), %s)
                        ON CONFLICT (key) DO UPDATE SET
                            value=EXCLUDED.value,
                            is_secret=true,
                            updated_at=now(),
                            updated_by=EXCLUDED.updated_by
                        """,
                        (secret_key, Jsonb(secret_value), actor_id),
                    )
                    secrets_ref[secret_name] = {
                        "key": secret_key,
                        "configured": True,
                    }

            cur.execute(
                """
                INSERT INTO plugin_settings (plugin_id, settings, secrets_ref, updated_at, updated_by)
                VALUES (%s, %s, %s, now(), %s)
                ON CONFLICT (plugin_id) DO UPDATE SET
                    settings=EXCLUDED.settings,
                    secrets_ref=EXCLUDED.secrets_ref,
                    updated_at=now(),
                    updated_by=EXCLUDED.updated_by
                """,
                (plugin_id, Jsonb(settings), Jsonb(secrets_ref), actor_id),
            )

            if plugin_is_metadata(categories) and table_exists(conn, "metadata_plugin_settings"):
                cur.execute(
                    """
                    INSERT INTO metadata_plugin_settings (
                        plugin_id,
                        settings,
                        secrets_ref,
                        updated_at,
                        updated_by
                    )
                    VALUES (%s, %s, %s, now(), %s)
                    ON CONFLICT (plugin_id) DO UPDATE SET
                        settings=EXCLUDED.settings,
                        secrets_ref=EXCLUDED.secrets_ref,
                        updated_at=now(),
                        updated_by=EXCLUDED.updated_by
                    """,
                    (plugin_id, Jsonb(settings), Jsonb(secrets_ref), actor_id),
                )


def client_entity_mapping(
    conn,
    *,
    client_id: str,
    entity_type: str,
    client_entity_id: str | None,
) -> UUID | None:
    if not client_entity_id:
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT entity_id
            FROM client_id_mappings
            WHERE user_id IS NULL
              AND client_id=%s
              AND entity_type=%s
            """,
            (f"{client_id}:{client_entity_id}", entity_type),
        )
        row = cur.fetchone()
    return row["entity_id"] if row else None


def store_client_entity_mapping(
    conn,
    *,
    client_id: str,
    client_entity_id: str | None,
    entity_type: str,
    entity_id: UUID,
    idem_key: str,
) -> None:
    if not client_entity_id:
        return
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO client_id_mappings (
                user_id,
                client_id,
                entity_type,
                entity_id,
                idempotency_key
            )
            VALUES (NULL, %s, %s, %s, %s)
            ON CONFLICT (user_id, client_id, entity_type) DO NOTHING
            """,
            (f"{client_id}:{client_entity_id}", entity_type, entity_id, idem_key),
        )


def movie_payload_fields(payload: dict[str, Any]) -> dict[str, Any]:
    metadata = payload.get("metadata")
    if not isinstance(metadata, dict):
        metadata = {}
    for source, target in (
        ("posterUrl", "poster_url"),
        ("backdropUrl", "backdrop_url"),
        ("poster_url", "poster_url"),
        ("backdrop_url", "backdrop_url"),
    ):
        if payload.get(source):
            metadata[target] = payload[source]
    return {
        "barcode": payload.get("barcode"),
        "title": payload.get("title"),
        "sort_title": payload.get("sortTitle") or payload.get("sort_title"),
        "original_title": payload.get("originalTitle") or payload.get("original_title"),
        "year": payload.get("year"),
        "release_date": payload.get("releaseDate") or payload.get("release_date"),
        "format": payload.get("format"),
        "edition": payload.get("edition"),
        "edition_type": payload.get("editionType") or payload.get("edition_type"),
        "country": payload.get("country"),
        "language": payload.get("language"),
        "runtime_minutes": payload.get("runtimeMinutes") or payload.get("runtime_minutes"),
        "overview": payload.get("overview"),
        "notes": payload.get("notes"),
        "rating": payload.get("rating"),
        "purchase_date": payload.get("purchaseDate") or payload.get("purchase_date"),
        "purchase_price": payload.get("purchasePrice") or payload.get("purchase_price"),
        "location": payload.get("location"),
        "metadata": metadata,
    }


MOVIE_EDIT_FIELD_LIMITS = {
    "title": 300,
    "sort_title": 300,
    "original_title": 300,
    "year": 40,
    "barcode": 160,
    "format": 80,
    "edition": 160,
    "country": 80,
    "language": 80,
    "location": 160,
    "overview": 5000,
    "notes": 5000,
}


def parse_optional_date(value: Any, field_name: str) -> date | None:
    text = clean_text(value)
    if not text:
        return None
    try:
        return date.fromisoformat(text)
    except ValueError as exc:
        raise NextApiError(f"{field_name} must use YYYY-MM-DD", 400) from exc


def movie_update_payload(body: dict[str, Any], *, existing: dict[str, Any]) -> dict[str, Any]:
    def pick_text(column: str, *aliases: str) -> str | None:
        keys = (column, *aliases)
        if any(key in body for key in keys):
            raw = next(body[key] for key in keys if key in body)
            value = clean_text(raw)
        else:
            value = existing.get(column)
        if value and len(str(value)) > MOVIE_EDIT_FIELD_LIMITS[column]:
            raise NextApiError(f"{column} must be {MOVIE_EDIT_FIELD_LIMITS[column]} characters or fewer", 400)
        return value

    if "releaseDate" in body or "release_date" in body:
        release_date = parse_optional_date(body.get("releaseDate", body.get("release_date")), "releaseDate")
    else:
        release_date = existing.get("release_date")

    title = pick_text("title")
    if not title:
        raise NextApiError("Movie title is required", 400)

    return {
        "title": title,
        "sort_title": pick_text("sort_title", "sortTitle"),
        "original_title": pick_text("original_title", "originalTitle"),
        "year": pick_text("year"),
        "barcode": pick_text("barcode"),
        "release_date": release_date,
        "format": pick_text("format"),
        "edition": pick_text("edition"),
        "country": pick_text("country"),
        "language": pick_text("language"),
        "overview": pick_text("overview"),
        "notes": pick_text("notes"),
        "location": pick_text("location"),
    }


