def metadata_refresh_jobs(
    conn,
    *,
    movie_id: UUID | None = None,
    status: str = "",
    limit: int = 50,
) -> list[dict[str, Any]]:
    if not table_exists(conn, "background_jobs"):
        return []
    clauses = ["job_type = %s"]
    params: list[Any] = [METADATA_REFRESH_JOB_TYPE]
    if movie_id:
        clauses.append("payload->>'movieId' = %s")
        params.append(str(movie_id))
    if status:
        clauses.append("status = %s")
        params.append(status)
    where = " AND ".join(clauses)
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                id,
                job_type,
                status,
                requested_by,
                payload,
                result,
                error,
                created_at,
                started_at,
                finished_at
            FROM background_jobs
            WHERE {where}
            ORDER BY created_at DESC
            LIMIT %s
            """,
            (*params, limit),
        )
        rows = cur.fetchall()
    return [job_row(row) for row in rows]


PUBLIC_NEXT_PATHS = {
    "/",
    "/app",
    "/app/",
    "/app/import",
    "/app/import/",
    "/ui-preview",
    "/ui-preview/",
    "/api/next/app",
    "/api/next/app/",
    "/api/next/app/import",
    "/api/next/app/import/",
    "/api/next/collection",
    "/api/next/collection/",
    "/api/next/health",
    "/api/next/i18n",
    "/api/next/manifest.json",
    "/api/next/ui-preview",
    "/api/next/ui-preview/",
    "/api/next/migration",
    "/api/next/migration/",
}
PUBLIC_NEXT_PREFIXES = (
    "/.well-known/",
    "/api/auth/",
    "/api/next/auth/",
    "/api/next/assets/",
    "/api/next/i18n/",
    "/api/next/media/assets/",
)


def is_public_next_path(path: str) -> bool:
    return path in PUBLIC_NEXT_PATHS or any(path.startswith(prefix) for prefix in PUBLIC_NEXT_PREFIXES)


def register_routes(flask_app: Flask) -> None:
    register_next_auth_routes(
        flask_app,
        connect=connect,
        table_exists=table_exists,
        response=response,
        next_api_error=NextApiError,
    )

    @flask_app.errorhandler(NextApiError)
    def handle_next_error(error: NextApiError):
        return response({"status": "error", "error": str(error)}, error.status_code)

    @flask_app.errorhandler(HTTPException)
    def handle_http_error(error: HTTPException):
        return response(
            {
                "status": "error",
                "error": error.description,
                "path": request.path,
            },
            error.code or 500,
        )

    @flask_app.errorhandler(Exception)
    def handle_unexpected_error(error: Exception):  # pragma: no cover - Flask integration
        flask_app.logger.exception("Unhandled Next API error on %s", request.path)
        return response({"status": "error", "error": str(error), "path": request.path}, 500)

    @flask_app.before_request
    def require_next_auth():
        if not (
            request.path == "/"
            or request.path.startswith(("/app", "/api/next", "/api/auth", "/.well-known"))
        ):
            return None
        if is_public_next_path(request.path):
            return None
        with connect() as conn:
            if not next_auth_effective_enabled(conn, table_exists):
                return None
            if next_auth_current_user(conn):
                return None
        return response(
            {
                "status": "error",
                "error": "Authentication required",
                "auth_required": True,
                "path": request.path,
            },
            401,
        )

    @flask_app.get("/api/next/health")
    def health():
        with connect() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        current_database() AS database,
                        current_user AS user,
                        version() AS postgres_version,
                        now() AS checked_at
                    """
                )
                db = cur.fetchone()
            migrations = migration_overview(conn)
        migration_state = migrations["state"]
        is_ready = migration_state == "ready"
        return response(
            {
                "status": "ok" if is_ready else "degraded",
                "service": "discvault-next-api",
                "version": build_version(),
                "sha": build_sha(),
                "database": db,
                "migrations": migrations,
            },
            200 if is_ready else 503,
        )

    @flask_app.get("/manifest.json")
    @flask_app.get("/api/next/manifest.json")
    def next_pwa_manifest():
        result = jsonify(pwa_manifest_payload())
        result.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        return result

    @flask_app.get("/service-worker.js")
    def next_service_worker():
        path = next_frontend_dir() / "service-worker.js"
        if not path.exists() or not path.is_file():
            raise NextApiError("Service worker not found", 404)
        result = send_file(path, mimetype="application/javascript")
        result.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        return result

    @flask_app.get("/api/next/assets/<path:asset_name>")
    def next_frontend_asset(asset_name: str):
        safe_name = Path(asset_name).name
        if safe_name != asset_name or safe_name not in PWA_ICON_ASSETS:
            raise NextApiError("Asset not found", 404)
        path = next_frontend_dir() / safe_name
        if not path.exists() or not path.is_file():
            raise NextApiError("Asset not found", 404)
        return send_file(path, mimetype=mimetypes.guess_type(path.name)[0] or "application/octet-stream")

    @flask_app.get("/api/next/flags/<path:flag_name>")
    def next_frontend_flag(flag_name: str):
        safe_name = Path(flag_name).name
        if safe_name != flag_name or not re.fullmatch(r"[a-z]{2}\.svg", safe_name):
            raise NextApiError("Flag not found", 404)
        path = next_frontend_dir() / "flags" / safe_name
        if not path.exists() or not path.is_file():
            raise NextApiError("Flag not found", 404)
        return send_file(path, mimetype="image/svg+xml")

