    @flask_app.patch("/api/next/preferences")
    def patch_app_preferences():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Preferences request body must be an object", 400)
        updates = body.get("preferences", body)
        if not isinstance(updates, dict):
            raise NextApiError("preferences must be an object", 400)
        with connect() as conn:
            user = next_auth_current_user(conn) if next_auth_effective_enabled(conn, table_exists) else None
            if next_auth_effective_enabled(conn, table_exists) and not user:
                raise NextApiError("Unauthorized", 401)
            if not user:
                # In unauthenticated development setups we keep the endpoint readable but do
                # not mutate global defaults from the app shell.
                return response(
                    {
                        "status": "ok",
                        "preferences": app_effective_preferences(conn),
                        "userScoped": False,
                        "updated": False,
                    }
                )
            with conn.transaction():
                preferences = set_app_user_preferences(conn, user["id"], updates)
        return response({"status": "ok", "preferences": preferences, "userScoped": True, "updated": True})

    @flask_app.get("/api/next/stats")
    def stats():
        with connect() as conn:
            counts = {
                "movies": count_table(conn, "movies"),
                "people": count_table(conn, "people"),
                "movieCredits": count_table(conn, "movie_credits"),
                "containers": count_table(conn, "containers"),
                "mediaGroups": count_table(conn, "media_groups"),
                "mediaAssets": count_table(conn, "media_assets"),
                "metadataPlugins": count_table(conn, "metadata_plugins"),
                "digitalMediaSources": count_table(conn, "digital_media_sources"),
                "digitalMediaItems": count_table(conn, "digital_media_items"),
                "users": count_table(conn, "users"),
            }
            container_counts = []
            plugin_counts = []
            latest_import = None
            if table_exists(conn, "containers"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT container_type, COUNT(*) AS count
                        FROM containers
                        GROUP BY container_type
                        ORDER BY container_type
                        """
                    )
                    container_counts = cur.fetchall()
            if table_exists(conn, "metadata_plugins"):
                reconcile_legacy_metadata_plugins(conn)
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT enabled, COUNT(*) AS count
                        FROM metadata_plugins
                        GROUP BY enabled
                        ORDER BY enabled DESC
                        """
                    )
                    plugin_counts = cur.fetchall()
            if table_exists(conn, "migration_runs"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT id, source_kind, status, started_at, completed_at, result
                        FROM migration_runs
                        ORDER BY started_at DESC
                        LIMIT 1
                        """
                    )
                    latest_import = cur.fetchone()
        return response(
            {
                "status": "ok",
                "counts": counts,
                "containersByType": container_counts,
                "metadataPluginsByEnabled": plugin_counts,
                "latestImport": latest_import,
            }
        )

