    @flask_app.get("/api/next/jobs/<job_id>")
    def get_job(job_id: str):
        job_uuid = parse_uuid(job_id, "jobId")
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                (
                    "admin.view_jobs",
                    "collection.import",
                    "admin.restore_functional",
                    "metadata.view_plugin_health",
                    "metadata.refresh_one",
                    "metadata.refresh_bulk",
                    "digital_sources.view",
                    "digital_sources.sync",
                    "digital_sources.manage",
                ),
            )
            if not table_exists(conn, "background_jobs"):
                raise NextApiError("Background job table is not available", 503)
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT
                        id,
                        job_type,
                        status,
                        requested_by,
                        payload,
                        result,
                        error,
                        created_at,
                        started_at,
                        finished_at
                    FROM background_jobs
                    WHERE id=%s
                    """,
                    (job_uuid,),
                )
                row = cur.fetchone()
        if not row:
            raise NextApiError("Job not found", 404)
        permissions = set(actor.get("permissions") or [])
        role = actor.get("role")
        if role != "owner" and "admin.view_jobs" not in permissions:
            if row["job_type"] == PLUGIN_EXECUTION_JOB_TYPE:
                plugin_job_permissions = {
                    "metadata.view_plugin_health",
                    "digital_sources.view",
                    "digital_sources.sync",
                    "digital_sources.manage",
                }
                if not permissions.intersection(plugin_job_permissions):
                    raise NextApiError("Permission required: admin.view_jobs", 403)
            elif row["job_type"] == METADATA_REFRESH_JOB_TYPE:
                if not permissions.intersection({"metadata.refresh_one", "metadata.refresh_bulk"}):
                    raise NextApiError("Permission required: admin.view_jobs", 403)
            elif row["job_type"] == MIGRATION_JOB_TYPE:
                if not permissions.intersection({"collection.import", "admin.restore_functional"}):
                    raise NextApiError("Permission required: admin.view_jobs", 403)
            else:
                raise NextApiError("Permission required: admin.view_jobs", 403)
        return response({"status": "ok", "job": job_row(row)})

    @flask_app.get("/api/next/backup/status")
    def backup_status():
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("collection.export_functional", "collection.import", "admin.restore_functional", "admin.view_jobs"),
            )
            counts = {table: count_table(conn, table) for table in TARGET_DATA_TABLES if table != "users"}
            counts["entity_media"] = count_table(conn, "entity_media")
            counts["movie_identifiers"] = count_table(conn, "movie_identifiers")
            counts["container_identifiers"] = count_table(conn, "container_identifiers")
            latest_jobs = []
            if table_exists(conn, "background_jobs"):
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        SELECT
                            id,
                            job_type,
                            status,
                            requested_by,
                            payload,
                            result,
                            error,
                            created_at,
                            started_at,
                            finished_at
                        FROM background_jobs
                        WHERE job_type=%s
                        ORDER BY created_at DESC
                        LIMIT 5
                        """,
                        (BACKUP_RESTORE_JOB_TYPE,),
                    )
                    latest_jobs = [job_row(row) for row in cur.fetchall()]
        data_dir = legacy_data_dir()
        backup_dir = backup_storage_dir(data_dir)
        return response(
            {
                "status": "ok",
                "scope": "functional_collection",
                "actor": {"role": actor.get("role"), "username": actor.get("username")},
                "dataDir": str(data_dir),
                "backupDir": str(backup_dir),
                "counts": counts,
                "latestJobs": latest_jobs,
            }
        )

    @flask_app.get("/api/next/backup/export")
    def backup_export():
        data_dir = legacy_data_dir()
        backup_dir = backup_storage_dir(data_dir)
        file_name = f"discvault-next-functional-{datetime.utcnow().strftime('%Y%m%d-%H%M%S')}.zip"
        output_path = backup_dir / file_name
        with connect() as conn:
            actor = require_next_permission(conn, "collection.export_functional")
            summary = export_functional_backup(
                conn,
                output_path,
                data_dir=data_dir,
                generator={
                    "service": "DiscVault Next",
                    "version": build_version(),
                    "sha": build_sha(),
                },
                requested_by=actor,
            )
            audit_event(
                conn,
                event_type="backup.exported",
                category="backup",
                actor=actor,
                target_type="backup",
                target_id=file_name,
                summary="Exported functional collection backup",
                metadata={"fileName": file_name, "sha256": summary.get("sha256"), "scope": "functional_collection"},
            )
        result = send_file(
            output_path,
            mimetype="application/zip",
            as_attachment=True,
            download_name=file_name,
            conditional=False,
        )
        result.headers["X-DiscVault-Backup-Sha256"] = summary["sha256"]
        result.headers["X-DiscVault-Backup-Scope"] = "functional_collection"
        return result

    @flask_app.post("/api/next/backup/validate")
    def backup_validate():
        data_dir = legacy_data_dir()
